  .priority { flex: none;""")
rep("""  </form>
  <div class="filters\"""", """  </form>
  <input class="search" data-testid="search-input" type="search" placeholder="Search todos" aria-label="Search todos" autocomplete="off">
  <div class="filters\"""")
rep("""  var currentFilter = 'all';
""", """  var currentFilter = 'all';
  var searchInput = document.querySelector('[data-testid="search-input"]');
  var searchTerm = '';
""")
rep("""  // [REQ-001] [REQ-002] [REQ-003] [REQ-004]
  function render() {""", """  // [REQ-007] Case-insensitive substring match on the todo text; an empty term matches everything.
  function matchesSearch(todo, term) {
    return todo.text.toLowerCase().indexOf(term.toLowerCase()) !== -1;
  }

  // [REQ-001] [REQ-002] [REQ-003] [REQ-004] [REQ-007]
  function render() {""")
rep("""    orderTodos(todos).filter(function (t) { return matchesFilter(t, currentFilter); }).forEach(""",
"""    // [REQ-007] Search narrows the filtered set; both must match.
    orderTodos(todos).filter(function (t) { return matchesFilter(t, currentFilter) && matchesSearch(t, searchTerm); }).forEach(""")
rep("""      text.textContent = todo.text;
""", """      text.textContent = todo.text;
      text.addEventListener('dblclick', function () { startEdit(text, todo); });
""")
rep("""  // [REQ-001]
  function deleteTodo(id) {""", """  // [REQ-007] Swap the text for an input. Enter or blur commits, Escape cancels.
  // Blank text on commit is treated as a cancel, so editing never deletes a todo.
  function startEdit(textEl, todo) {
    var field = document.createElement('input');
    field.type = 'text';
    field.className = 'edit';
    field.setAttribute('data-testid', 'todo-edit-input');
    field.setAttribute('aria-label', 'Edit todo');
    field.value = todo.text;
    var finished = false;
    function finish(commit) {
      if (finished) return;
      finished = true;
      if (commit) editTodo(todo.id, field.value);
      else render();
    }
    field.addEventListener('keydown', function (e) {
      if (e.key === 'Enter') { e.preventDefault(); finish(true); }
      else if (e.key === 'Escape') { e.preventDefault(); finish(false); }
    });
    field.addEventListener('blur', function () { finish(true); });
    textEl.replaceWith(field);
    field.focus();
    field.select();
  }

  // [REQ-007]
  function editTodo(id, rawText) {
    var text = rawText.trim();
    if (text) {
      todos.forEach(function (t) { if (t.id === id) t.text = text; });
      saveTodos();
    }
    render();
  }

  // [REQ-001]
  function deleteTodo(id) {""")
rep("""  form.addEventListener('submit',""", """  // [REQ-007]
  searchInput.addEventListener('input', function () {
    searchTerm = searchInput.value;
    render();
  });

  form.addEventListener('submit',""")
open(p,'w').write(s)
